"""Original CARS passages, batch 2 (5 humanities, 5 social science), 7 questions each.
Question tuples: (category R1/R2/R3, stem, right answer, [(wrong, why) x3], [explanation lines])."""

P = []


def cars(pid, unit, title, paras, qs):
    text = "\n".join(f"<p>{p}</p>" for p in paras)
    out = []
    for c, q, right, wrong, e in qs:
        assert len(wrong) == 3
        out.append({"c": c, "q": q, "o": [right] + [w[0] for w in wrong], "a": 0, "e": e, "w": [""] + [w[1] for w in wrong]})
    P.append({"id": pid, "s": "cars", "subj": "cars", "unit": unit, "title": title, "text": text, "qs": out})


